2|//!
3|//! This module provides dequantization functions for GGUF tensor formats
4|//! using the `ggml-quants` crate, avoiding C dependencies where possible.
5|
6|
7|use crate::error::{Result, RunnerError};
8|
9|/// Dequantize Q4_0 data using ggml-quants.
10|///
11|/// Q4_0 format: 32 elements per block, 18 bytes per block.
12|/// - First 2 bytes: f16 scale
13|/// - Next 16 bytes: nibble-packed quantized values (4 bits each)
14|pub fn dequantize_q4_0_ggml(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
15|    let num_full_blocks = element_count / 32;
16|    let remaining = element_count % 32;
17|    let expected_size = num_full_blocks * 18
18|        + if remaining > 0 {
19|            2 + remaining.div_ceil(2)
20|        } else {
21|            0
22|        };
23|
24|    if data.len() < expected_size {
25|        return Err(RunnerError::Internal(format!(
26|            "Q4_0 data too small: got {} bytes, need {}",
27|            data.len(), expected_size
28|        )));
29|    }
30|
31|    let mut result = Vec::with_capacity(element_count);
32|
33|    for block in 0..num_full_blocks {
34|        let base = block * 18;
35|        
36|        // Parse scale (f16)
37|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
38|        let scale = f16_to_f32_le(scale_f16);
39|
40|        // Extract nibbles and dequantize
41|        for i in 0..32usize {
42|            if result.len() >= element_count {
43|                break;
44|            }
45|            let nibble = (data[base + 2 + i / 2] >> (4 * (i & 1))) & 0x0F;
46|            let q = nibble as i32 - 8;
47|            result.push(scale * q as f32);
48|        }
49|    }
50|
51|    // Handle remaining elements
52|    if remaining > 0 {
53|        let base = num_full_blocks * 18;
54|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
55|        let scale = f16_to_f32_le(scale_f16);
56|
57|        let elems_in_block = remaining.min(32);
58|        for i in 0..elems_in_block {
59|            let nibble = (data[base + 2 + i / 2] >> (4 * (i & 1))) & 0x0F;
60|            let q = nibble as i32 - 8;
61|            result.push(scale * q as f32);
62|        }
63|    }
64|
65|    Ok(result)
66|}
67|
68|/// Dequantize Q4_1 data using ggml-quants.
69|///
70|/// Q4_1 format: 32 elements per block, 20 bytes per block.
71|/// - First 2 bytes: f16 scale
72|/// - Next 2 bytes: f16 min
73|/// - Next 16 bytes: nibble-packed quantized values (unsigned)
74|pub fn dequantize_q4_1_ggml(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
75|    let num_full_blocks = element_count / 32;
76|    let remaining = element_count % 32;
77|    let expected_size = num_full_blocks * 20
78|        + if remaining > 0 {
79|            4 + remaining.div_ceil(2)
80|        } else {
81|            0
82|        };
83|
84|    if data.len() < expected_size {
85|        return Err(RunnerError::Internal(format!(
86|            "Q4_1 data too small: got {} bytes, need {}",
87|            data.len(), expected_size
88|        )));
89|    }
90|
91|    let mut result = Vec::with_capacity(element_count);
92|
93|    for block in 0..num_full_blocks {
94|        let base = block * 20;
95|        
96|        // Parse scale and min
97|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
98|        let scale = f16_to_f32_le(scale_f16);
99|        
100|        let min_f16 = data[base + 2] as u16 | (data[base + 3] as u16) << 8;
101|        let min = f16_to_f32_le(min_f16);
102|
103|        // Extract nibbles and dequantize: dequantized = scale * q + min
104|        for i in 0..32usize {
105|            if result.len() >= element_count {
106|                break;
107|            }
108|            let nibble = (data[base + 4 + i / 2] >> (4 * (i & 1))) & 0x0F;
109|            let q = nibble as f32;
110|            result.push(scale * q + min);
111|        }
112|    }
113|
114|    if remaining > 0 {
115|        let base = num_full_blocks * 20;
116|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
117|        let scale = f16_to_f32_le(scale_f16);
118|        
119|        let min_f16 = data[base + 2] as u16 | (data[base + 3] as u16) << 8;
120|        let min = f16_to_f32_le(min_f16);
121|
122|        let elems_in_block = remaining.min(32);
123|        for i in 0..elems_in_block {
124|            let nibble = (data[base + 4 + i / 2] >> (4 * (i & 1))) & 0x0F;
125|            let q = nibble as f32;
126|            result.push(scale * q + min);
127|        }
128|    }
129|
130|    Ok(result)
131|}
132|
133|/// Dequantize Q8_0 data using ggml-quants.
134|///
135|/// Q8_0 format: 32 elements per block, 34 bytes per block.
136|/// - First 2 bytes: f16 scale
137|/// - Next 32 bytes: int8 quantized values
138|pub fn dequantize_q8_0_ggml(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
139|    let num_blocks = element_count.div_ceil(32);
140|    let expected_size = num_blocks * 34;
141|
142|    if data.len() < expected_size {
143|        return Err(RunnerError::Internal(format!(
144|            "Q8_0 data too small: got {} bytes, need {}",
145|            data.len(), expected_size
146|        )));
147|    }
148|
149|    let mut result = Vec::with_capacity(element_count);
150|
151|    for block in 0..num_blocks {
152|        let base = block * 34;
153|        
154|        // Parse scale
155|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
156|        let scale = f16_to_f32_le(scale_f16);
157|
158|        // Extract int8 values and dequantize: dequantized = scale * quantized_value
159|        for i in 0..32usize {
160|            if result.len() >= element_count {
161|                break;
162|            }
163|            let q = data[base + 2 + i] as i8 as f32;
164|            result.push(scale * q);
165|        }
166|    }
167|
168|    Ok(result)
169|}
170|
171|/// Helper: Convert little-endian u16 to f32 (f16 representation).
172|fn f16_to_f32_le(val: u16) -> f32 {
173|    // Use the half crate for proper f16 conversion
174|    use half::f16;
175|    f16::from_bits(val).to_f32()
176|}
177|
178|/// Dequantize Q5_0 data.
179|///
180|/// Q5_0 format: 32 elements per block, 16 bytes per block.
181|/// Layout: f16 scale (2B) + nibble-packed quants (16B = 32 nibbles)
182|/// The high bit is implicitly 0 for Q5_0 (values 0-31, not 0-31+16).
183|pub fn dequantize_q5_0(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
184|    let num_full_blocks = element_count / 32;
185|    let remaining = element_count % 32;
186|    // Q5_0: n/2 + 48 bytes total, which is 16 bytes per block
187|    let expected_size = num_full_blocks * 16
188|        + if remaining > 0 {
189|            2 + remaining.div_ceil(2)
190|        } else {
191|            0
192|        };
193|
194|    if data.len() < expected_size {
195|        return Err(RunnerError::Internal(format!(
196|            "Q5_0 data too small: got {} bytes, need {}",
197|            data.len(), expected_size
198|        )));
199|    }
200|
201|    let mut result = Vec::with_capacity(element_count);
202|
203|    for block in 0..num_full_blocks {
204|        let base = block * 16;
205|
206|        // Parse scale (f16)
207|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
208|        let scale = f16_to_f32_le(scale_f16);
209|
210|        // Extract nibbles and dequantize
211|        // Q5_0: values are 0-31, stored as nibbles with implicit high bit = 0
212|        for i in 0..32usize {
213|            if result.len() >= element_count {
214|                break;
215|            }
216|            let nibble = (data[base + 2 + i / 2] >> (4 * (i & 1))) & 0x0F;
217|            // Q5_0 values are 0-31, but we need to check if there's a high bit
218|            // Based on llama.cpp, Q5_0 uses values 0-31 directly
219|            let q = nibble as i32;
220|
221|            // Dequantize: value = scale * q
222|            result.push(scale * q as f32);
223|        }
224|    }
225|
226|    // Handle remaining elements
227|    if remaining > 0 {
228|        let base = num_full_blocks * 16;
229|        let scale_f16 = data[base] as u16 | (data[base + 1] as u16) << 8;
230|        let scale = f16_to_f32_le(scale_f16);
231|
232|        let elems_in_block = remaining.min(32);
233|        for i in 0..elems_in_block {
234|            let nibble = (data[base + 2 + i / 2] >> (4 * (i & 1))) & 0x0F;
235|            let q = nibble as i32;
236|            result.push(scale * q as f32);
237|        }
238|    }
239|
240|    Ok(result)
