{"content": "1|//! GGUF weight loading with dequantization.
2|//!
3|//! Loads tensors from a GGUF file into memory, dequantizing Q4_0 and converting
4|//! F16/BF16 to f32. Returns a `GgufWeights` struct that can be fed directly into
5|//! the inference engine.
6|//!
7|//! ## Supported dtypes
8|//!
9|//! - F32 — passthrough
10|//! - F16 / BF16 — convert to f32
11|//! - Q4_0 — dequantize to f32 (32 elements per block)
12|//! - Q4_1 — dequantize to f32
13|//! - Q8_0 — dequantize to f32
14|//! - I8 / I16 / I32 / I64 — passthrough
15|//!
16|
17|use std::collections::HashMap;
18|use std::path::Path;
19|
20|use pesti_gguf::parser::{extract_tensor_bytes_from_path, parse_gguf};
21|use pesti_gguf::types::{GgufDtype, GgufHeader, GgufTensorInfo};
22|
23|use crate::dequantize::{
24|    dequantize_q4_0_ggml, dequantize_q4_1_ggml, dequantize_q5_0, dequantize_q8_0_ggml,
25|};
26|use crate::error::{Result, RunnerError};
27|use half::f16;
28|
29|/// A loaded GGUF model's tensors in memory.
30|#[derive(Debug, Clone)]
31|pub struct GgufWeights {
32|    /// Parsed GGUF header with model config.
33|    pub header: GgufHeader,
34|    /// Tensor data: name → dequantized f32 bytes.
35|    pub tensors: HashMap<String, Vec<u8>>,
36|}
37|
38|impl GgufWeights {
39|    /// Get the shape of a tensor as `(in_features, out_features)`.
40|    ///
41|    /// GGUF stores weight tensors as `[in_features, out_features]`.
42|    /// Returns `(0, 0)` if the tensor is not found or has wrong ndims.
43|    pub fn tensor_shape(&self, name: &str) -> (usize, usize) {
44|        self.header
45|            .get_tensor(name)
46|            .and_then(|t| {
47|                if t.shape.len() >= 2 {
48|                    Some((t.shape[0] as usize, t.shape[1] as usize))
49|                } else {
50|                    None
51|                }
52|            })
53|            .unwrap_or((0, 0))
54|    }
55|}
56|
57|/// Load all tensors from a GGUF file into memory.
58|pub fn load_gguf_weights(gguf_path: &Path) -> Result<GgufWeights> {
59|    let header = parse_gguf(gguf_path)?;
60|    let mut tensors = HashMap::with_capacity(header.tensors.len());
61|
62|    for tensor in &header.tensors {
63|        let stored_size = tensor.stored_size() as usize;
64|        let file_offset = header.data_section_start + tensor.offset;
65|        let raw_data = extract_tensor_bytes_from_path(gguf_path, file_offset, stored_size)?;
66|        let dequantized = dequantize_tensor(tensor, &raw_data)?;
67|        tensors.insert(tensor.name.clone(), dequantized);
68|    }
69|
70|    Ok(GgufWeights { header, tensors })
71|}
72|
73|/// Load a single tensor from a GGUF file.
74|pub fn load_gguf_tensor(gguf_path: &Path, tensor_name: &str) -> Result<(GgufHeader, Vec<u8>)> {
75|    let header = parse_gguf(gguf_path)?;
76|    let tensor = header.get_tensor(tensor_name).ok_or_else(|| {
77|        RunnerError::Gguf(pesti_gguf::GgufError::InvalidTensor(format!(
78|            "tensor '{tensor_name}' not found in file"
79|        )))
80|    })?;
81|
82|    let stored_size = tensor.stored_size() as usize;
83|    let file_offset = header.data_section_start + tensor.offset;
84|    let raw_data = extract_tensor_bytes_from_path(gguf_path, file_offset, stored_size)?;
85|    let dequantized = dequantize_tensor(tensor, &raw_data)?;
86|
87|    Ok((header, dequantized))
88|}
89|
90|/// Dequantize tensor data to f32 bytes based on GGUF dtype.
91|fn dequantize_tensor(tensor: &GgufTensorInfo, raw_data: &[u8]) -> Result<Vec<u8>> {
92|    let dtype = GgufDtype::from_u32(tensor.dtype);
93|    let claimed_element_count = tensor.element_count() as usize;
94|
95|    // Detect dtype mismatch: reverse inference for K-family quant types
96|    let (inferred_dtype, inferred_element_count) = if matches!(
97|        dtype,
98|        GgufDtype::Q4_K | GgufDtype::Q4_K_M | GgufDtype::Q4_K_S
99|            | GgufDtype::Q5_K | GgufDtype::Q5_K_M | GgufDtype::Q5_K_S
100|            | GgufDtype::Q6_K | GgufDtype::Q6_K_S
101|            | GgufDtype::Q8_K | GgufDtype::Q8_K_M
102|            | GgufDtype::Q2_K | GgufDtype::Q2_K_S | GgufDtype::Q2_K_M
103|            | GgufDtype::Q3_K | GgufDtype::Q3_K_S
104|            | GgufDtype::Q1_K
105|    ) {
106|        // For K-family, use the claimed dtype but recalculate element count from data size
107|        let (block_size, elements_per_block) = match dtype {
108|            GgufDtype::Q4_K | GgufDtype::Q4_K_M | GgufDtype::Q4_K_S => (28, 16),
109|            GgufDtype::Q5_K | GgufDtype::Q5_K_M | GgufDtype::Q5_K_S => (36, 16),
110|            GgufDtype::Q6_K | GgufDtype::Q6_K_S => (42, 16),
111|            GgufDtype::Q8_K | GgufDtype::Q8_K_M => (40, 16),
112|            GgufDtype::Q2_K | GgufDtype::Q2_K_S | GgufDtype::Q2_K_M => (32, 16),
113|            GgufDtype::Q3_K | GgufDtype::Q3_K_S => (24, 16),
114|            GgufDtype::Q1_K => (20, 16),
115|            // Non-K-family quant types - shouldn't reach here but just in case
116|            _ => return dequantize_tensor(tensor, raw_data),
117|        };
118|
119|        let num_blocks = raw_data.len() / block_size;
120|        let inferred_count = num_blocks * elements_per_block;
121|
122|        (dtype, inferred_count)
123|    } else {
124|        // Non-K-family types - use claimed values
125|        (dtype, claimed_element_count)
126|    };
127|
128|    tracing::debug!(
129|        tensor = %tensor.name,
130|        dtype = ?dtype,
131|        elements = claimed_element_count,
132|        bytes = raw_data.len(),
133|        "Dequantizing tensor"
134|    );
135|    if inferred_dtype != dtype || inferred_element_count != claimed_element_count {
136|        tracing::warn!(
137|            inferred_dtype = ?inferred_dtype,
138|            inferred_elements = inferred_element_count,
139|            claimed_dtype = ?dtype,
140|            claimed_elements = claimed_element_count,
141|            "Dtype/element count mismatch — using inferred values from data size"
142|        );
143|    }
144|
145|    match inferred_dtype {
146|        GgufDtype::F32 => Ok(raw_data.to_vec()),
147|        GgufDtype::F16 => {
148|            let f32_data = half_f32(raw_data);
149|            Ok(f32_data.into_iter().flat_map(|v| v.to_le_bytes()).collect())
150|        }
151|        GgufDtype::BF16 => {
152|            let f32_data = bf16_f32(raw_data);
153|            Ok(f32_data.into_iter().flat_map(|v| v.to_le_bytes()).collect())
154|        }
155|        GgufDtype::Q4_0 => {
156|            let dequantized = dequantize_q4_0_ggml(raw_data, inferred_element_count)
157|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
158|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
159|        }
160|        GgufDtype::Q4_1 => {
161|            let dequantized = dequantize_q4_1_ggml(raw_data, inferred_element_count)
162|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
163|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
164|        }
165|        GgufDtype::Q5_0 => {
166|            let dequantized = dequantize_q5_0(raw_data, inferred_element_count)
167|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
168|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
169|        }
170|        GgufDtype::Q5_1 => {
171|            let dequantized = dequantize_q5_0(raw_data, inferred_element_count)
172|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
173|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
174|        }
175|        GgufDtype::Q8_0 => {
176|            let dequantized = dequantize_q8_0_ggml(raw_data, inferred_element_count)
177|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
178|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
179|        }
180|        GgufDtype::Q2_K => {
181|            let dequantized = dequantize_q2_k(raw_data, inferred_element_count)
182|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
183|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
184|        }
185|        GgufDtype::Q3_K => {
186|            let dequantized = dequantize_q3_k(raw_data, inferred_element_count)
187|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
188|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
189|        }
190|        GgufDtype::Q4_K | GgufDtype::Q4_K_M => {
191|            let dequantized = dequantize_q4_k(raw_data, inferred_element_count)
192|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
193|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
194|        }
195|        GgufDtype::Q5_K | GgufDtype::Q5_K_M | GgufDtype::Q5_K_S => {
196|            let dequantized = dequantize_q5_k(raw_data, inferred_element_count)
197|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
198|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
199|        }
200|        GgufDtype::Q6_K | GgufDtype::Q6_K_S => {
201|            match dequantize_q6_k(raw_data, inferred_element_count) {
202|                Ok(result) => Ok(result.into_iter().flat_map(|v| v.to_le_bytes()).collect()),
203|                Err(_) => {
204|                    Ok(vec![])
205|                }
206|            }
207|        }
208|        GgufDtype::Q8_K | GgufDtype::Q8_K_M => {
209|            let dequantized = dequantize_q8_k(raw_data, inferred_element_count)
210|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
211|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
212|        }
213|        GgufDtype::Q1_K => {
214|            let dequantized = dequantize_q1_k(raw_data, inferred_element_count)
215|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
216|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
217|        }
218|        GgufDtype::Q2_K_S => {
219|            let dequantized = dequantize_q2_k(raw_data, inferred_element_count)
220|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
221|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
222|        }
223|        GgufDtype::Q3_K_S => {
224|            let dequantized = dequantize_q3_k(raw_data, inferred_element_count)
225|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
226|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
227|        }
228|        GgufDtype::Q4_K_S => {
229|            let dequantized = dequantize_q4_k(raw_data, inferred_element_count)
230|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
231|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
232|        }
233|        GgufDtype::Q2_K_M => {
234|            let dequantized = dequantize_q2_k(raw_data, inferred_element_count)
235|                .map_err(|e| RunnerError::Dequant(tensor.name.clone(), e.to_string()))?;
236|            Ok(dequantized.into_iter().flat_map(|v| v.to_le_bytes()).collect())
237|        }
238|        GgufDtype::I8 | GgufDtype::I16 | GgufDtype::I32 | GgufDtype::I64 => Ok(raw_data.to_vec()),
239|        GgufDtype::Unknown(_) => Err(RunnerError::Gguf(pesti_gguf::GgufError::Io(format!(
240|            "Unknown GGUF dtype {} for tensor '{}'",
241|            tensor.dtype, tensor.name
242|        )))),
243|        _ => Err(RunnerError::Gguf(pesti_gguf::GgufError::Io(format!(
244|            "Unsupported GGUF dtype {} for tensor '{}'",
245|            tensor.dtype, tensor.name
246|        )))),
247|    }
