250|// ── K-family dequantization implementations ─────────────────────────
251|
252|fn dequantize_q1_k(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
253|    let num_full_blocks = element_count / 16;
254|    let remaining = element_count % 16;
255|    let expected_size = num_full_blocks * 20
256|        + if remaining > 0 { 2 + remaining.div_ceil(2) } else { 0 };
257|
258|    if data.len() < expected_size {
259|        return Err(RunnerError::Gguf(pesti_gguf::GgufError::Io(format!(
260|            "Q1_K data too small: got {} bytes, need {}",
261|            data.len(), expected_size
262|        ))));
263|    }
264|
265|    let mut result = Vec::with_capacity(element_count);
266|    let mut offset = 0usize;
267|
268|    for _ in 0..num_full_blocks {
269|        let d = f16_to_f32(&data[offset..offset + 2]);
270|        let d_min = f16_to_f32(&data[offset + 2..offset + 4]);
271|        let q1 = u16::from_le_bytes([data[offset + 4], data[offset + 5]]);
272|        let _delta = [
273|            f16_to_f32(&data[offset + 6..offset + 8]),
274|            f16_to_f32(&data[offset + 8..offset + 10]),
275|            f16_to_f32(&data[offset + 10..offset + 12]),
276|            f16_to_f32(&data[offset + 12..offset + 14]),
277|        ];
278|        let h = [
279|            f16_to_f32(&data[offset + 14..offset + 16]),
280|            f16_to_f32(&data[offset + 16..offset + 18]),
281|            f16_to_f32(&data[offset + 18..offset + 20]),
282|            f16_to_f32(&data[offset + 20..offset + 22]),
283|        ];
284|
285|        for i in 0..16usize {
286|            let q1_val = (((q1 >> i) & 0x01) as u16) << 2;
287|            let q = q1_val as i32 - 4;
288|            let scale = if q1_val > 0 { h[i / 4] } else { 1.0 };
289|            result.push(d * (q as f32) * scale + d_min);
290|        }
291|        offset += 20;
292|    }
293|
294|    if remaining > 0 {
295|        let d = f16_to_f32(&data[offset..offset + 2]);
296|        let d_min = f16_to_f32(&data[offset + 2..offset + 4]);
297|        let q1 = u16::from_le_bytes([data[offset + 4], data[offset + 5]]);
298|        let h = [
299|            f16_to_f32(&data[offset + 14..offset + 16]),
300|            f16_to_f32(&data[offset + 16..offset + 18]),
301|            f16_to_f32(&data[offset + 18..offset + 20]),
302|            f16_to_f32(&data[offset + 20..offset + 22]),
303|        ];
304|
305|        for i in 0..remaining {
306|            let q1_val = (((q1 >> i) & 0x01) as u16) << 2;
307|            let q = q1_val as i32 - 4;
308|            let scale = if q1_val > 0 { h[i / 4] } else { 1.0 };
309|            result.push(d * (q as f32) * scale + d_min);
310|        }
311|    }
312|
313|    Ok(result)
314|}
