316|fn dequantize_q2_k(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
317|    let num_full_blocks = element_count / 16;
318|    let remaining = element_count % 16;
319|    let expected_size = (num_full_blocks * 17 + if remaining > 0 { 2 } else { 0 }) as usize;
320|
321|    if data.len() < expected_size {
322|        return Err(RunnerError::Internal(format!(
323|            "Q2_K data too small: got {} bytes, need {}",
324|            data.len(), expected_size
325|        )));
326|    }
327|
328|    let mut result = Vec::with_capacity(element_count);
329|    let mut offset = 0usize;
330|
331|    for _ in 0..num_full_blocks {
332|        let d = f16_to_f32(&data[offset..offset + 2]);
333|        let d_min = f16_to_f32(&data[offset + 2..offset + 4]);
334|        let q1 = u8::from_le_bytes([data[offset + 4]]);
335|        let q2 = u32::from_le_bytes([
336|            data[offset + 5],
337|            data[offset + 6],
338|            data[offset + 7],
339|            data[offset + 8],
340|        ]);
341|        let h = [
342|            f16_to_f32(&data[offset + 9..offset + 11]),
343|            f16_to_f32(&data[offset + 11..offset + 13]),
344|            f16_to_f32(&data[offset + 13..offset + 15]),
345|            f16_to_f32(&data[offset + 15..offset + 17]),
346|        ];
347|
348|        for i in 0..16usize {
349|            let q2_val = ((q2 >> (2 * i)) & 0x03) as u16;
350|            let q1_val = (((q1 >> i) & 0x01) as u16) << 2;
351|            let q = (q1_val | q2_val) as i32 - 4;
352|            let scale = if q2_val > 0 { h[i / 4] } else { 1.0 };
353|            result.push(d * (q as f32) * scale + d_min);
354|        }
355|        offset += 17;
356|    }
357|
358|    if remaining > 0 {
359|        let d = f16_to_f32(&data[offset..offset + 2]);
360|        let _d_min = f16_to_f32(&data[offset + 2..offset + 4]);
361|        let q1 = u8::from_le_bytes([data[offset + 4]]);
362|        let q2 = u32::from_le_bytes([
363|            data[offset + 5],
364|            data[offset + 6],
365|            data[offset + 7],
366|            data[offset + 8],
367|        ]);
368|
369|        for i in 0..remaining {
370|            let q2_val = ((q2 >> (2 * i)) & 0x03) as u16;
371|            let q1_val = (((q1 >> i) & 0x01) as u16) << 2;
372|            let q = (q1_val | q2_val) as i32 - 4;
373|            result.push(d * (q as f32));
374|        }
375|    }
376|
377|    Ok(result)
378|}
