380|fn dequantize_q3_k(data: &[u8], element_count: usize) -> Result<Vec<f32>> {
381|    let num_full_blocks = element_count / 16;
382|    let remaining = element_count % 16;
383|    let expected_size = num_full_blocks * 21 + if remaining > 0 { 3 } else { 0 };
384|
385|    if data.len() < expected_size {
386|        return Err(RunnerError::Gguf(pesti_gguf::GgufError::Io(format!(
387|            "Q3_K data too small: got {} bytes, need {}",
388|            data.len(), expected_size
389|        ))));
390|    }
391|
392|    let mut result = Vec::with_capacity(element_count);
393|    let mut offset = 0usize;
394|
395|    for _ in 0..num_full_blocks {
396|        let d = f16_to_f32(&data[offset..offset + 2]);
397|        let d_min = f16_to_f32(&data[offset + 2..offset + 4]);
398|        let _delta = data[offset + 4];
399|        let k_scale = [
400|            data[offset + 5],
401|            data[offset + 6],
402|            data[offset + 7],
403|            data[offset + 8],
404|        ];
405|        let _mask = data[offset + 9];
406|        let q3 = u32::from_le_bytes([
407|            data[offset + 10],
408|            data[offset + 11],
409|            data[offset + 12],
410|            data[offset + 13],
411|        ]);
412|        let _h = [
413|            f16_to_f32(&data[offset + 14..offset + 16]),
414|            f16_to_f32(&data[offset + 16..offset + 18]),
415|            f16_to_f32(&data[offset + 18..offset + 20]),
416|            f16_to_f32(&data[offset + 20..offset + 22]),
417|        ];
418|
419|        for i in 0..16usize {
420|            let q3_val = ((q3 >> (2 * i)) & 0x03) as u16;
421|            let q = (q3_val as i32 - 4) as f32 * k_scale[i / 4] as f32;
422|            result.push(d * q + d_min);
423|        }
424|        offset += 21;
425|    }
426|
427|    if remaining > 0 {
428|        let d = f16_to_f32(&data[offset..offset + 2]);
429|        let d_min = f16_to_f32(&data[offset + 2..offset + 4]);
